UPDATE runtime_operations SET status='delivery_unknown',worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='delivering' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND ordinal=?5 AND status='unknown');